('homepage_config','{\"version\":\"2.6\",\"lastPublishedAt\":\"2026-10-03T12:15:05.719Z\",\"sectionOrder\":[\"hero\",\"about\",\"features\",\"modules\",\"benefits\",\"contact\",\"footer\"],\"hero\":{\"enabled\":true,\"badgeText\":\"Maintenance Department ERP\",\"badgeTag\":\"v3.8 LIVE\",\"title\":\"AL-MUSLIM GROUP\",\"titleHighlight\":\"MAINTENANCE DEPARTMENT ERP\",\"subtitle\":\"Maintenance Department ERP System\",\"description\":\"Manage machine inventory, machine transfers, spare parts replacement, manpower allocation, and complete equipment lifetime history from one centralized system across all manufacturing floors and production units.\",\"primaryBtnText\":\"User Login\",\"primaryBtnAction\":\"login\",\"secondaryBtnText\":\"Explore Machine Registry\",\"secondaryBtnAction\":\"inventory\",\"showLiveMetrics\":true},\"about\":{\"enabled\":true,\"title\":\"Engineered for Heavy Garments & Apparel Plants\",\"subtitle\":\"System Architecture & Capabilities\",\"description\":\"Designed specifically for Al-Muslim Group composite knit, woven, and denim factories. The platform bridges mechanical maintenance teams, floor supervisors, store managers, and industrial engineering departments.\",\"stats\":[{\"label\":\"Factory Units Connected\",\"value\":\"4 Factories\",\"icon\":\"🏭\"},{\"label\":\"Active Sewing & Specialized Lines\",\"value\":\"38 Lines\",\"icon\":\"🧵\"},{\"label\":\"Uptime Reliability Index\",\"value\":\"99.4%\",\"icon\":\"⚡\"},{\"label\":\"Barcode Scanning Accuracy\",\"value\":\"100%\",\"icon\":\"🏷️\"}]},\"features\":{\"enabled\":true,\"title\":\"Core System Capabilities\",\"subtitle\":\"State-of-the-Art Factory Operations\",\"items\":[{\"id\":\"feat-1\",\"icon\":\"📦\",\"title\":\"7-Level Machinery Catalog\",\"description\":\"Complete physical machine asset register with group, unit, floor, line, brand, model, and barcode tag tracking.\",\"status\":\"ACTIVE\",\"order\":1},{\"id\":\"feat-2\",\"icon\":\"🔄\",\"title\":\"Relocation & Transfer Ledger\",\"description\":\"Multi-level workflow approval engine for inter-floor, inter-factory, and external repair machine movements.\",\"status\":\"ACTIVE\",\"order\":2},{\"id\":\"feat-3\",\"icon\":\"⚙️\",\"title\":\"Spare Parts Replacement Matrix\",\"description\":\"Inventory tracking, fitted part histories, minimum stock warnings, and automated parts consumption ledger.\",\"status\":\"ACTIVE\",\"order\":3},{\"id\":\"feat-4\",\"icon\":\"👥\",\"title\":\"Workforce & Manpower Placement\",\"description\":\"Registry of mechanics, senior technicians, and floor line supervisors with custom skill grades and leave tracking.\",\"status\":\"ACTIVE\",\"order\":4},{\"id\":\"feat-5\",\"icon\":\"📜\",\"title\":\"Digital Machine Passport\",\"description\":\"Complete lifetime lifecycle logs documenting every service, breakdown, line transfer, and spare part replacement.\",\"status\":\"ACTIVE\",\"order\":5},{\"id\":\"feat-6\",\"icon\":\"📊\",\"title\":\"Excel Import / Export Hub\",\"description\":\"Instant roster and inventory upload/download in Microsoft Excel format with real-time error auditing.\",\"status\":\"ACTIVE\",\"order\":6}]},\"modules\":{\"enabled\":true,\"title\":\"Integrated ERP Modules\",\"subtitle\":\"Explore the Complete Suite of Industrial Plant Systems\",\"items\":[{\"id\":\"mod-1\",\"icon\":\"📦\",\"name\":\"Machine Inventory\",\"description\":\"Search, filter, view specifications, status badges, and barcode labels for all plant machinery.\",\"badge\":\"Core Asset\",\"targetView\":\"inventory\",\"status\":\"ACTIVE\",\"order\":1},{\"id\":\"mod-2\",\"icon\":\"👥\",\"name\":\"Manpower Management\",\"description\":\"Workforce roster, employee relocations, dynamic parameters, and attendance records.\",\"badge\":\"Workforce\",\"targetView\":\"manpower\",\"status\":\"ACTIVE\",\"order\":2},{\"id\":\"mod-3\",\"icon\":\"🔄\",\"name\":\"Machine Transfers\",\"description\":\"Transfer request authorization, floor movement records, and printed gate passes.\",\"badge\":\"Operations\",\"targetView\":